#include <algorithm>
#include <cstdint>
#include <ranges>
#include <utility>
#include <variant>

#include "rt/core.hpp"
#include "rt/harness.hpp"
#include "rt/text.hpp"
#include "rt/trace.hpp"
#include "support.hpp"
#include "todo/board.hpp"
#include "todo/model.hpp"
#include "todo/render.hpp"

namespace todo {

namespace {

// Traces per law; each of 40 steps, every law checked after every step.
constexpr std::uint64_t traces = 240;
constexpr int steps = 40;
// A trace starts from the initial world, or every third from a world a test's @given set up.
board::World start(std::uint64_t seed) {
  return seed % 3 == 0 ? support::given_three_open_one_done() : board::World{};
}
// Runs one event; true when its rule refused.
bool refused(board::Event event, board::World& w) {
  board::Lines out;
  return !board::apply(std::move(event), w, out).has_value();
}
// `event.no`: every rule of the trace has it.
model::TaskNo event_no(const board::Event& e) {
  return std::visit(
      [](const auto& x) -> model::TaskNo {
        if constexpr (requires { x.no; }) {
          return x.no;
        } else {
          harness::fail("the event has no no");
        }
      },
      e);
}

// An event of a trace over add | done | reopen | rename | remove | clear: each rule evenly.
board::Event draw_change(rt::random::Prng& prng) {
  switch (prng.below(6)) {
    case 0:
      return board::Add{.title = support::gen_title(prng),
                        .priority = support::gen_priority(prng),
                        .tags = support::gen_tag_set(prng)};
    case 1:
      return board::Done{.no = support::gen_task_no(prng)};
    case 2:
      return board::Reopen{.no = support::gen_task_no(prng)};
    case 3:
      return board::Rename{.no = support::gen_task_no(prng), .title = support::gen_title(prng)};
    case 4:
      return board::Remove{.no = support::gen_task_no(prng)};
    case 5:
      return board::Clear{};
  }
  std::unreachable();
}

// An event of a trace over add: each rule evenly.
board::Event draw_add(rt::random::Prng& prng) {
  switch (prng.below(1)) {
    case 0:
      return board::Add{.title = support::gen_title(prng),
                        .priority = support::gen_priority(prng),
                        .tags = support::gen_tag_set(prng)};
  }
  std::unreachable();
}

// An event of a trace over done | reopen | rename | remove: each rule evenly.
board::Event draw_done_or_reopen_or_rename_or_remove(rt::random::Prng& prng) {
  switch (prng.below(4)) {
    case 0:
      return board::Done{.no = support::gen_task_no(prng)};
    case 1:
      return board::Reopen{.no = support::gen_task_no(prng)};
    case 2:
      return board::Rename{.no = support::gen_task_no(prng), .title = support::gen_title(prng)};
    case 3:
      return board::Remove{.no = support::gen_task_no(prng)};
  }
  std::unreachable();
}

// An event of a trace over list | stats: each rule evenly.
board::Event draw_list_or_stats(rt::random::Prng& prng) {
  switch (prng.below(2)) {
    case 0:
      return board::List{.all = support::gen_bool(prng), .tag = support::gen_tag_option(prng)};
    case 1:
      return board::Stats{};
  }
  std::unreachable();
}

}  // namespace

// a number is never reused.
TEST(numbers_below_next) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t =
        rt::test::trace<board::World, board::Event>(seed, start(seed), steps, draw_change, refused);
    CHECK(std::ranges::all_of(t.states(), [&](const auto& w) {
      return std::ranges::all_of(w.tasks | std::views::keys, [&](const auto& it) { return it < w.next_no; });
    }));
  }
}

// only add moves the counter, and only up.
TEST(next_only_grows) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t = rt::test::trace<board::World, board::Event>(seed, start(seed), steps, draw_add, refused);
    CHECK(
        std::ranges::all_of(t.steps, [&](const auto& it) { return it.after.next_no >= it.before.next_no; }));
  }
}

// a command that names a task touches no other task.
TEST(others_untouched) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t = rt::test::trace<board::World, board::Event>(
        seed, start(seed), steps, draw_done_or_reopen_or_rename_or_remove, refused);
    rt::random::Prng prng = rt::random::Prng(seed + 24301);
    for (int q = 0; q < 8; ++q) {
      const auto k = support::gen_task_no(prng);
      CHECK(std::ranges::all_of(t.steps, [&](const auto& s) {
        return event_no(s.event) == k || rt::get(s.after.tasks, k) == rt::get(s.before.tasks, k);
      }));
    }
  }
}

TEST(clear_keeps_every_open_task) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t =
        rt::test::trace<board::World, board::Event>(seed, start(seed), steps, draw_change, refused);
    CHECK(std::ranges::all_of(t.steps, [&](const auto& s) {
      return !std::holds_alternative<board::Clear>(s.event) ||
             (std::ranges::all_of(s.after.tasks | std::views::values,
                                  [&](const auto& it) { return it.status == model::Status::Open; }) &&
              rt::length(s.after.tasks) ==
                  rt::length(s.before.tasks | std::views::values | std::views::filter([&](const auto& it) {
                               return it.status == model::Status::Open;
                             })));
    }));
  }
}

TEST(reads_change_nothing) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t =
        rt::test::trace<board::World, board::Event>(seed, start(seed), steps, draw_list_or_stats, refused);
    CHECK(std::ranges::all_of(t.steps, [&](const auto& it) { return it.after == it.before; }));
  }
}

// a refused command leaves the board as it was.
TEST(refusal_changes_nothing) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t =
        rt::test::trace<board::World, board::Event>(seed, start(seed), steps, draw_change, refused);
    CHECK(std::ranges::all_of(t.steps, [&](const auto& s) { return !s.refused || s.after == s.before; }));
  }
}

// a task is stored under its own number.
TEST(stored_under_its_number) {
  for (std::uint64_t seed = 0; seed < traces; ++seed) {
    const auto t =
        rt::test::trace<board::World, board::Event>(seed, start(seed), steps, draw_change, refused);
    CHECK(std::ranges::all_of(t.states(), [&](const auto& w) {
      return std::ranges::all_of(w.tasks | std::views::keys,
                                 [&](const auto& k) { return w.tasks.at(k).no == k; });
    }));
  }
}

}  // namespace todo
